        char *trace_bits = av_malloc(65 * sizeof(char));
        if (!trace_bits) {
            return AVERROR(ENOMEM);
        }
        snprintf(trace_bits, 65, "%s", bits);
        av_log(ctx->log_ctx, AV_LOG_TRACE, "Read uvlc %s: value %u (0x%x) at position %d, bits %s.\n",
               name, value, value, position, trace_bits);
        av_free(trace_bits);
    }

    return 0;
